# Checks R/fit_qtree.R against reference outputs of the authors' QTree package
# (generated by tests/make_reference_qtree.py; see that file).
# Run from the project root:  Rscript tests/test_fit_qtree.R

source("main/load_packages.R")

ref <- "tests/reference"
meta <- jsonlite::read_json(file.path(ref, "meta.json"), simplifyVector = TRUE)
n_checks <- 0L

check <- function(ok, what) {
  if (!isTRUE(ok)) stop("FAILED: ", what, call. = FALSE)
  n_checks <<- n_checks + 1L
  message("ok  ", what)
}

# numpy writes missing values as "nan"
read_mat <- function(file) {
  unname(as.matrix(read.csv(file, header = FALSE, na.strings = c("nan", "NA"))))
}

river <- readRDS("data/river_clean_declustered.rds")

for (dataset in c("dataset-1", "dataset-6")) {
  X <- as.matrix(read.csv(file.path(ref, paste0(dataset, "-X.csv"))))
  d <- ncol(X)
  order <- seq_len(d)  # columns are in causal order

  # 0. The test input is log(x + 1) of the stated rows of the declustered data
  idx <- scan(file.path(ref, paste0(dataset, "-subsample_idx.csv")), quiet = TRUE)
  X_data <- log(as.matrix(river[idx, colnames(X)]) + 1)
  check(isTRUE(all.equal(unname(X), unname(X_data), tolerance = 1e-12)),
        paste(dataset, "input matches the river data"))

  for (q in meta$q_grid) {
    tag <- paste0(dataset, " q=", q)

    # 1. Score matrix vs the package's quantileDispersion
    S_ref <- read_mat(file.path(ref, sprintf("%s-scores-q%s.csv", dataset, q)))
    S <- unname(qtree_scores(X, q = q, small_r = meta$small_r))
    check(identical(is.na(S), is.na(S_ref)) &&
            isTRUE(all.equal(S[!is.na(S)], S_ref[!is.na(S_ref)], tolerance = 1e-10)),
          paste(tag, "scores"))

    # 2. Order-restricted tree vs Edmonds on the forward edges
    T_ref <- read_mat(file.path(ref, sprintf("%s-tree-q%s.csv", dataset, q)))
    check(all(order_restricted_tree(S_ref, order, type = "min") == T_ref),
          paste(tag, "restricted tree from reference scores"))
    check(all(unname(fit_qtree_fixed(X, order, q = q, small_r = meta$small_r)) == T_ref),
          paste(tag, "restricted tree from data"))
  }

  # 3. Centroid and variability from the package's trees on fixed subsamples
  rows <- read_mat(file.path(ref, paste0(dataset, "-centroid-trees.csv")))
  trees <- lapply(seq_len(nrow(rows)), function(l) matrix(rows[l, ], d, d, byrow = TRUE))

  centroid_ref <- read_mat(file.path(ref, paste0(dataset, "-centroid-restricted.csv")))
  check(all(qtree_centroid(trees, order) == centroid_ref),
        paste(dataset, "restricted centroid"))

  # Same formula as QTree.fitToSamples: evaluate it at the package's centroid
  centroid_pkg <- read_mat(file.path(ref, paste0(dataset, "-centroid-package.csv")))
  var_ref <- meta$cases$var_T_package[which(meta$cases$dataset == dataset &
                                              !is.na(meta$cases$var_T_package))]
  check(isTRUE(all.equal(qtree_variability(trees, centroid_pkg), var_ref,
                         tolerance = 1e-12)),
        paste(dataset, "variability Var(T)"))
}

message("\nAll ", n_checks, " checks passed.")
